using namespace std;

long long modInverse(long long a, long long m) {
    long long m0 = m, t, q;
    long long x0 = 0, x1 = 1;
    if (m == 1) return 0;
    while (a > 1) {
        q = a / m;
        t = m;
        m = a % m, a = t;
        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
}

int main() {
    long long p, k;
    cin >> p >> k;
    const long long pcon = 1000000007;
    vector<long long> inv_table(1000003, 0);
    inv_table[1] = 1;
    for (long long i = 2; i < 1000003; ++i) {
        long long a = pcon / i;
        long long b = pcon % i;
        long long c = (a * (pcon - inv_table[b])) % pcon;
        inv_table[i] = c;
    }
    long long total_ans = 0;
    if (k == 0) {
        total_ans = 1;
        for (long long i = 0; i < p - 1; ++i) {
            total_ans = (total_ans * p) % pcon;
        }
